create table if not exists public.service_agreements(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,name text not null,status text not null default 'active' check(status in('active','past_due','paused','canceled','expired')),billing_frequency text,price numeric(12,2),started_on date,renews_on date,ends_on date,visits_per_year integer not null default 0,visits_remaining integer not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index if not exists service_agreements_customer_idx on public.service_agreements(customer_id); create index if not exists service_agreements_renewal_idx on public.service_agreements(renews_on) where status='active'; alter table public.service_agreements enable row level security; revoke all on public.service_agreements from anon; grant select,insert,update on public.service_agreements to authenticated;
create table if not exists public.service_agreement_visits(id uuid primary key default gen_random_uuid(),agreement_id uuid not null references public.service_agreements(id) on delete cascade,job_id uuid references public.jobs(id) on delete set null,scheduled_for date,completed_at timestamptz,status text not null default 'due' check(status in('due','scheduled','completed','skipped','canceled')),notes text,created_at timestamptz not null default now()); create index if not exists service_agreement_visits_agreement_idx on public.service_agreement_visits(agreement_id); alter table public.service_agreement_visits enable row level security; revoke all on public.service_agreement_visits from anon; grant select,insert,update on public.service_agreement_visits to authenticated;
create table if not exists public.sales_opportunities(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,job_id uuid references public.jobs(id) on delete set null,equipment_id uuid references public.customer_equipment(id) on delete set null,source text not null default 'manual',title text not null,category text,stage text not null default 'new' check(stage in('new','contacting','qualified','estimate_sent','won','lost','deferred')),estimated_value numeric(12,2),reason text,next_follow_up_at timestamptz,owner_id uuid references public.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),closed_at timestamptz); create index if not exists sales_opportunities_customer_idx on public.sales_opportunities(customer_id); create index if not exists sales_opportunities_followup_idx on public.sales_opportunities(next_follow_up_at) where stage not in('won','lost'); alter table public.sales_opportunities enable row level security; revoke all on public.sales_opportunities from anon; grant select,insert,update on public.sales_opportunities to authenticated;
create or replace function private.service_agreement_dashboard() returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v jsonb; begin if not public.has_permission_for_current_user('view_customers') then raise exception 'Customer permission required'; end if; select jsonb_build_object('active',(select count(*) from public.service_agreements where status='active'),'renewing30',(select count(*) from public.service_agreements where status='active' and renews_on between current_date and current_date+30),'visitsDue',(select count(*) from public.service_agreement_visits where status='due' and scheduled_for<=current_date+30),'pastDue',(select count(*) from public.service_agreements where status='past_due'),'agreements',coalesce((select jsonb_agg(to_jsonb(q) order by q.renews_on nulls last) from (select a.*,c.name customer_name,c.phone,c.email from public.service_agreements a join public.customers c on c.id=a.customer_id where a.status in('active','past_due','paused') order by a.renews_on nulls last limit 200) q),'[]'::jsonb)) into v; return v; end $$; create or replace function public.service_agreement_dashboard() returns jsonb language sql stable set search_path='' as $$ select private.service_agreement_dashboard() $$; revoke all on function public.service_agreement_dashboard() from public,anon; grant execute on function public.service_agreement_dashboard() to authenticated;
create or replace function private.service_titan_opportunity_feed() returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v jsonb; begin if not public.has_permission_for_current_user('view_opportunities') then raise exception 'Opportunity permission required'; end if; select jsonb_build_object('estimates',coalesce((select jsonb_agg(payload order by coalesce(nullif(payload->>'modifiedOn',''),nullif(payload->>'createdOn','')) desc nulls last) from public.service_titan_records where resource='estimates' limit 300),'[]'::jsonb),'equipment',coalesce((select jsonb_agg(payload order by coalesce(nullif(payload->>'modifiedOn',''),nullif(payload->>'createdOn','')) desc nulls last) from public.service_titan_records where resource='equipment' limit 500),'[]'::jsonb),'memberships',coalesce((select jsonb_agg(payload order by nullif(payload->>'modifiedOn','') desc nulls last) from public.service_titan_records where resource='memberships' limit 200),'[]'::jsonb)) into v; return v; end $$; create or replace function public.service_titan_opportunity_feed() returns jsonb language sql stable set search_path='' as $$ select private.service_titan_opportunity_feed() $$; revoke all on function public.service_titan_opportunity_feed() from public,anon; grant execute on function public.service_titan_opportunity_feed() to authenticated;